'use client'

import * as React from 'react'
import { badgeVariants, cn, type BadgeVariants } from "@/lib/utils"
import type { VariantProps } from 'class-variance-authority'

import { Slot } from './slot'

function Badge({
  className,
  variant,
  asChild = false,
  ...props
}: React.ComponentProps<'span'> & VariantProps<typeof badgeVariants> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'span'

  return <Comp data-slot="badge" className={cn(badgeVariants({ variant }), className)} {...props} />
}

export { Badge, badgeVariants }

import { cva, type VariantProps } from 'class-variance-authority'

export const badgeVariants = cva(
  'inline-flex items-center justify-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2',
  {
    variants: {
      variant: {
        default: 'border-transparent bg-primary text-primary-foreground shadow hover:bg-primary/80',
        secondary:
          'border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80',
        destructive: 'border-transparent bg-destructive text-white shadow hover:bg-destructive/80',
        outline: 'text-foreground',
      },
    },
    defaultVariants: {
      variant: 'default',
    },
  }
)

Component({
  properties: {
    variant: {
      type: String,
      value: 'default',
    },
    extClass: {
      type: String,
      value: '',
    },
  },
  data: {
    className: '',
  },
  lifetimes: {
    attached() {
      this.setData({
        className: badgeVariants({
          variant: this.properties.variant as any,
          className: this.properties.extClass,
        }),
      })
    },
  },
  observers: {
    'variant, extClass': function (variant, extClass) {
      this.setData({
        className: badgeVariants({ variant: variant as any, className: extClass }),
      })
    },
  },
})
